use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let jobs: Vec<i64> = input["jobs"].as_array().unwrap().iter().map(|job| job.as_i64()).collect();
    let quantum: i64 = input["quantum"].as_i64().unwrap();
    let mut indices = Vec::new();
    let mut work = jobs[0];
    for _ in 0..quantum {
        let next_index = (work + 1) % jobs.len();
        indices.push(next_index);
        work = jobs[next_index];
    }
    indices.sort_unstable();
    indices.into_iter().map(|&index| serde_json::Value::from(index)).collect()
}

fn main() {
    let input = serde_json::Value::from("{\"jobs\":[3,1,2],"quantum":2}");
    let output = solve(input);
    println!("{:?}", output);
}
